import test from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import {search} from '../src/engine.js';
test('installation contains all four verified original PDFs and searchable NCR articles',async()=>{const registry=JSON.parse(await readFile('dist/sources/registry.json'));assert.equal(registry.length,4);assert.equal(registry.reduce((n,s)=>n+s.pages,0),934);const docs=[];for(const s of registry){const bytes=await readFile('dist/sources/'+s.file);assert.equal(createHash('sha256').update(bytes).digest('hex'),s.hash);const d=JSON.parse(await readFile('dist/sources/'+s.index));assert.equal(d.pages.length,s.pages);assert.ok(d.chunks.length);docs.push(d);}const chunks=docs.find(d=>d.kind==='base').chunks;const h=search(chunks,'fire extinguisher mountings 25g');assert.equal(h[0].page,278);assert.match(h[0].reference,/Ch.7 App.6 Art.3.8/);});
